insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Составьте: Хотя формат стал короче, оговорка о недостатке данных сохранилась.','["Choć forma stała się krótsza, zachowano zastrzeżenie dotyczące braku danych.","Forma była krótka, więc usunięto wszystkie zastrzeżenia.","Brak danych krótszą formę zachowano."]',0,'Choć вводит уступку, а zachowano точно фиксирует сохранённый элемент.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Составьте: То, что в отчёте было предпосылкой, в подкасте нужно назвать прямо.','["To, co w raporcie było założeniem, w podcaście trzeba nazwać wprost.","Raport wprost ukrywa wszystko w podcaście.","Założenie trzeba raportem było nazwać."]',0,'Конструкция to, co... связывает функцию элемента в двух жанрах.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Która wersja zachowuje stopień pewności?','["Badanie sugeruje związek, ale go nie dowodzi.","Badanie bezsprzecznie dowodzi związku.","Związku na pewno nie ma."]',0,'Sugeruje сохраняет исходную эпистемическую осторожность.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Jak skompresować argument bez spłaszczenia?','["Zachować tezę, kluczowy dowód i ograniczenie.","Pozostawić tylko efektowną puentę.","Usunąć wszystkie warunki."]',0,'Минимальный инвариант включает тезис, основание и границы вывода.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Która eksplicytacja jest uzasadniona?','["Wyjaśnienie skrótu nieznanego nowej grupie odbiorców.","Dopisanie autorowi ukrytej motywacji.","Zamiana hipotezy w fakt."]',0,'Раскрытие неизвестной аббревиатуры помогает адресату и не меняет позицию автора.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-grammar','Co należy oznaczyć jako redakcyjną ramę?','["Tytuł interpretujący materiał, którego nie było w oryginale.","Dosłowny cytat z raportu.","Datę publikacji źródła."]',0,'Новый интерпретирующий заголовок должен быть отделён от исходного материала.',5,true);
