insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Jakie zastrzeżenie zawierał raport?','["Nie badano wpływu światła na owady","Nie mierzono zużycia energii","Nie podano okresu badania"]',0,'Экологическое влияние не входило в исследование.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Co zniekształcał pierwszy scenariusz?','["Zamieniał częściowy wynik w całościowy sukces","Dodawał zbyt wiele tabel","Cytował badaczkę dosłownie"]',0,'Он неоправданно расширял область вывода.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Jak zastąpiono tabelę?','["Wypowiedzią badaczki","Muzyką","Reklamą fundacji"]',0,'В аудиоформате данные сопровождались репликой исследовательницы.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Dlaczego zastrzeżenie przesunięto bliżej wniosku?','["Aby nie wyglądało na mało ważny dodatek","Aby je ukryć","Aby wydłużyć audycję"]',0,'Композиция сохранила вес ограничения.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Jak oznaczono scenę spaceru?','["Jako rekonstrukcję, nie dowód","Jako wynik eksperymentu","Jako cytat z raportu"]',0,'Редакционная рамка была обозначена прозрачно.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c25-reading-check','Co pozostało niezmienne między gatunkami?','["Hierarchia faktów i stopień pewności","Kolejność wszystkich zdań","Długość materiału"]',0,'Именно эти инварианты названы в финале.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c25-tekst','c2-cross-genre','Межжанровая трансформация','Переносим содержание между жанрами, сохраняя факты, нюансы и авторскую позицию','C2',16,'🔄','["Fundacja opublikowała obszerny raport o nocnym oświetleniu miasta. Autorzy stwierdzili spadek zużycia energii po wymianie lamp, lecz zastrzegli, że nie badali wpływu światła na owady. Redakcja lokalnego radia miała zamienić raport w trzyminutową audycję.","Pierwszy scenariusz brzmiał atrakcyjnie: «Nowe lampy rozwiązują miejski problem energii». Usuwał jednak warunek porównania i zamieniał częściowy wynik w całościowy sukces. Producentka wypisała więc inwarianty: zakres badania, zaobserwowany spadek, okres pomiaru oraz brak danych ekologicznych.","W audycji liczby skondensowano do dwóch najważniejszych wartości. Termin techniczny wyjaśniono krótkim porównaniem, a tabelę zastąpiła wypowiedź badaczki. Zastrzeżenie o owadach przesunięto bliżej głównego wniosku, aby słuchacz nie odebrał go jako drobnego dodatku.","Zmienił się też punkt widzenia. Raport prowadził czytelnika przez metodę, natomiast radio zaczynało od nocnego spaceru mieszkanki. Ta scena pełniła funkcję wejścia w temat, lecz producentka zaznaczyła, że jest rekonstrukcją, a nie dowodem naukowym.","Gotowy materiał różnił się rytmem, językiem i kompozycją od raportu. Zachował jednak hierarchię faktów oraz stopień pewności autorów. Transformacja nie była skrótem mechanicznym: wymagała rozpoznania funkcji każdego elementu i znalezienia dla niej uczciwego odpowiednika w nowym gatunku."]','{"konwencja gatunkowa":{"lemma":"konwencja gatunkowa","translation":"жанровая конвенция","part_of_speech":"wyrażenie rzeczownikowe"},"dominanta tekstu":{"lemma":"dominanta tekstu","translation":"доминанта текста","part_of_speech":"wyrażenie rzeczownikowe"},"kompresja treści":{"lemma":"kompresja treści","translation":"сжатие содержания","part_of_speech":"wyrażenie rzeczownikowe"},"eksplicytacja":{"lemma":"eksplicytacja","translation":"экспликация","part_of_speech":"rzeczownik"},"zmiana rejestru":{"lemma":"zmiana rejestru","translation":"смена регистра","part_of_speech":"wyrażenie rzeczownikowe"},"rama interpretacyjna":{"lemma":"rama interpretacyjna","translation":"интерпретационная рамка","part_of_speech":"wyrażenie rzeczownikowe"},"adresat docelowy":{"lemma":"adresat docelowy","translation":"целевая аудитория","part_of_speech":"wyrażenie rzeczownikowe"},"hierarchia faktów":{"lemma":"hierarchia faktów","translation":"иерархия фактов","part_of_speech":"wyrażenie rzeczownikowe"},"przeformułować przekaz":{"lemma":"przeformułować przekaz","translation":"переформулировать сообщение","part_of_speech":"wyrażenie czasownikowe"},"zachować zastrzeżenie":{"lemma":"zachować zastrzeżenie","translation":"сохранить оговорку","part_of_speech":"wyrażenie czasownikowe"},"dopowiedzieć kontekst":{"lemma":"dopowiedzieć kontekst","translation":"эксплицировать контекст","part_of_speech":"wyrażenie czasownikowe"},"skondensować argument":{"lemma":"skondensować argument","translation":"сжать аргумент","part_of_speech":"wyrażenie czasownikowe"},"zmienić punkt widzenia":{"lemma":"zmienić punkt widzenia","translation":"изменить точку зрения","part_of_speech":"wyrażenie czasownikowe"},"uniknąć spłaszczenia sensu":{"lemma":"uniknąć spłaszczenia sensu","translation":"избежать упрощения смысла","part_of_speech":"wyrażenie czasownikowe"},"przełożyć formę na funkcję":{"lemma":"przełożyć formę na funkcję","translation":"перевести форму в функцию","part_of_speech":"fraza"},"notatka prasowa":{"lemma":"notatka prasowa","translation":"пресс-релиз","part_of_speech":"wyrażenie rzeczownikowe"},"esej osobisty":{"lemma":"esej osobisty","translation":"личное эссе","part_of_speech":"wyrażenie rzeczownikowe"},"streszczenie wykonawcze":{"lemma":"streszczenie wykonawcze","translation":"резюме для руководства","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c25-reading-check"}',61,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
