insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c26-grammar','c2-cultural-interpretation','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Связываем форму, исторический контекст и конкурирующие прочтения произведения',14,'🎭','Интерпретация культуры','[["Интерпретация как гипотеза","Связывай наблюдаемую форму с контекстом через аргумент, а не свободную ассоциацию. Сильное прочтение объясняет несколько деталей и допускает проверку конкурирующей версией."],["Исторический и современный читатель","Различай вероятное намерение автора, эффект для первой аудитории и сегодняшнее восприятие. Анахроничное прочтение может быть продуктивным, если оно честно обозначено."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',318,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
