insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Составьте: Это прочтение убедительно постольку, поскольку объясняет повторяющийся образ окна.','["Odczytanie jest przekonujące o tyle, o ile wyjaśnia powracający obraz okna.","Odczytanie przekonuje, mimo że niczego nie wyjaśnia.","Obraz okna o tyle odczytanie."]',0,'O tyle, o ile ограничивает силу вывода объяснительной способностью.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Составьте: Нельзя исключить, что современный зритель видит в сцене другой конфликт.','["Nie można wykluczyć, że współczesny widz dostrzega w scenie inny konflikt.","Współczesny widz musi widzieć dokładnie to samo.","Scena wyklucza widza konflikt."]',0,'Nie można wykluczyć сохраняет открытость альтернативной интерпретации.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Co jest argumentem, a nie luźnym skojarzeniem?','["Motyw powraca w trzech scenach i za każdym razem poprzedza zmianę decyzji bohatera.","Okno kojarzy mi się z wolnością.","Autor na pewno myślał tak jak ja."]',0,'Повторяемая формальная связь делает гипотезу проверяемой.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Jak oddzielić intencję od efektu?','["Autor mógł nawiązać do mitu, ale dzisiejsi widzowie odczytują scenę także ekologicznie.","Efekt zawsze dowodzi intencji.","Intencja odbiorcy nie ma znaczenia."]',0,'Формулировка отдельно описывает вероятный замысел и современную реакцию.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Które zdanie uczciwie oznacza anachronizm?','["Z dzisiejszej perspektywy można zobaczyć tu problem, którego epoka nie nazywała w ten sposób.","Bohater używał pojęcia powstałego sto lat później.","Kontekst historyczny jest zbędny."]',0,'Современная рамка явно названа, а не приписана эпохе.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-grammar','Jak porównać konkurencyjne odczytania?','["Sprawdzić, które wyjaśnia więcej szczegółów przy mniejszej liczbie założeń.","Wybrać bardziej efektowne.","Uznać każde za równie mocne."]',0,'Сравнение опирается на объяснительную силу и экономность предпосылок.',5,true);
