insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-reading-check','Co wspierało interpretację emigracyjną?','["Rytm kroków, pusty stół i biograficzny podpis","Tylko kolor ścian","Cena instalacji"]',0,'Версия связывала несколько независимых деталей.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-reading-check','Na co wskazywało odbicie etykiet w lustrze?','["Na rolę muzeum w tworzeniu dziedzictwa","Na błąd techniczny","Na portret kuratorki"]',0,'Этот элемент поддерживал институциональное прочтение.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-reading-check','Dlaczego kuratorka nie wybrała jednej interpretacji?','["Obie wyjaśniały różne elementy","Nie znała instalacji","Artystka zakazała rozmowy"]',0,'Конкурирующие гипотезы имели разную объяснительную область.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-reading-check','Co wykraczało poza deklarowaną intencję artystki?','["Efekt muzealnej aranżacji","Motyw przeprowadzki","Nagranie kroków"]',0,'Текст отделяет авторскую декларацию от эффекта экспозиции.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c26-reading-check','Jak tekst definiuje odpowiedzialną interpretację?','["Jako mocną, ale rewizowalną hipotezę","Jako dowolne skojarzenie","Jako odtworzenie jednej intencji"]',0,'Финал подчёркивает одновременно обоснованность и открытость пересмотру.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c26-tekst','c2-cultural-interpretation','Интерпретация культуры','Связываем форму, исторический контекст и конкурирующие прочтения произведения','C2',16,'🎭','["W małej galerii pokazano instalację złożoną z pustego stołu, pękniętego lustra i nagrania kroków. Kuratorka opisała ją jako rozmowę z tradycją rodzinnego portretu. Część publiczności widziała przede wszystkim opowieść o emigracji, inni — krytykę pamięci tworzonej przez muzea.","Pierwsze odczytanie wspierał rytm nagrania: kroki oddalały się, gdy na lustrze pojawiało się światło. Pusty stół przywoływał nieobecnych, a podpis artystki wspominał o przeprowadzce jej rodziny. Interpretacja emigracyjna łączyła więc formę, biografię i powtarzalny motyw.","Drugie odczytanie zwracało uwagę na sposób ekspozycji. Lustro odbijało etykiety muzealne zamiast twarzy widza, a stół stał za barierą typową dla cennych zabytków. Instalacja mogła pytać, kto decyduje, które ślady codzienności stają się oficjalnym dziedzictwem.","Kuratorka nie rozstrzygnęła sporu. Zaznaczyła, że wypowiedzi artystki wspierają temat migracji, lecz efekt muzealnej aranżacji wykracza poza deklarowaną intencję. Obie interpretacje wyjaśniały inne elementy i mogły się uzupełniać, dopóki nie ignorowały niewygodnych szczegółów.","Rozmowa pokazała, że kontekst nie jest kluczem otwierającym jedno poprawne znaczenie. Ogranicza dowolność, dostarcza przesłanek i ujawnia anachronizmy, ale dzieło działa również w nowych horyzontach oczekiwań. Odpowiedzialna interpretacja pozostaje mocną, lecz rewizowalną hipotezą."]','{"kontekst kulturowy":{"lemma":"kontekst kulturowy","translation":"культурный контекст","part_of_speech":"wyrażenie rzeczownikowe"},"aluzja literacka":{"lemma":"aluzja literacka","translation":"литературная аллюзия","part_of_speech":"wyrażenie rzeczownikowe"},"intertekstualność":{"lemma":"intertekstualność","translation":"интертекстуальность","part_of_speech":"rzeczownik"},"symbolika":{"lemma":"symbolika","translation":"символика","part_of_speech":"rzeczownik"},"konwencja epoki":{"lemma":"konwencja epoki","translation":"конвенция эпохи","part_of_speech":"wyrażenie rzeczownikowe"},"strategia narracyjna":{"lemma":"strategia narracyjna","translation":"нарративная стратегия","part_of_speech":"wyrażenie rzeczownikowe"},"perspektywa odbiorcy":{"lemma":"perspektywa odbiorcy","translation":"перспектива читателя","part_of_speech":"wyrażenie rzeczownikowe"},"konkurencyjne odczytanie":{"lemma":"konkurencyjne odczytanie","translation":"конкурирующее прочтение","part_of_speech":"wyrażenie rzeczownikowe"},"osadzić w kontekście":{"lemma":"osadzić w kontekście","translation":"поместить в контекст","part_of_speech":"wyrażenie czasownikowe"},"uruchomić skojarzenie":{"lemma":"uruchomić skojarzenie","translation":"активировать ассоциацию","part_of_speech":"wyrażenie czasownikowe"},"podważyć interpretację":{"lemma":"podważyć interpretację","translation":"поставить интерпретацию под сомнение","part_of_speech":"wyrażenie czasownikowe"},"uzasadnić odczytanie":{"lemma":"uzasadnić odczytanie","translation":"обосновать прочтение","part_of_speech":"wyrażenie czasownikowe"},"oddzielić intencję od efektu":{"lemma":"oddzielić intencję od efektu","translation":"отделить намерение от эффекта","part_of_speech":"wyrażenie czasownikowe"},"uwzględnić anachronizm":{"lemma":"uwzględnić anachronizm","translation":"учесть анахронизм","part_of_speech":"wyrażenie czasownikowe"},"pozostawać w dialogu z tradycją":{"lemma":"pozostawać w dialogu z tradycją","translation":"вести диалог с традицией","part_of_speech":"fraza"},"pamięć zbiorowa":{"lemma":"pamięć zbiorowa","translation":"коллективная память","part_of_speech":"wyrażenie rzeczownikowe"},"kod wizualny":{"lemma":"kod wizualny","translation":"визуальный код","part_of_speech":"wyrażenie rzeczownikowe"},"horyzont oczekiwań":{"lemma":"horyzont oczekiwań","translation":"горизонт ожиданий","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c26-reading-check"}',62,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
